export const logoKey = (name?: string | null) =>
  (name ?? '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')

export const logoFor = (...names: (string | null | undefined)[]): string | null => {
  for (const n of names) {
    const hit = BRAND_LOGOS[logoKey(n)]
    if (hit) return hit
  }
  return null
}
